{"file_text": "@using sv_a6db39f9c5d949e8b5cc28961e285fa2.Models
@inject IJSRuntime JS

<div class="message-area">
    <div class="area-header">
        <h3># @Channel?.Name</h3>
        <span class="area-description">@Channel?.Description</span>
    </div>

    <div class="message-list" @ref="messageListRef" @onscroll="HandleScroll">
        @if (IsLoadingMore)
        {
            <div class="loading-indicator">Loading older messages…</div>
        }

        @foreach (var message in Messages)
        {
            <MessageItem Message="message"
                         ThreadInfo="GetThreadInfo(message.Id)"
                         OnOpenThread="OnOpenThread"
                         OnReact="OnReact" />
        }
    </div>

    <MessageInput Placeholder="@($"Message #{Channel?.Name}")"
                  ButtonLabel="Send"
                  OnSend="OnSendMessage" />
</div>

@code {
    [Parameter, EditorRequired] public Channel? Channel { get; set; }
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = [];
    [Parameter] public List<ThreadSummary> ThreadSummaries { get; set; } = [];
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public EventCallback OnLoadOlderMessages { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    private ElementReference messageListRef;
    private bool hasScrolledToBottom;

    private ThreadSummary? GetThreadInfo(int messageId) =>
        ThreadSummaries.FirstOrDefault(t => t.RootMessageId == messageId);

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (!hasScrolledToBottom && Messages.Count > 0)
        {
            hasScrolledToBottom = true;
            await ScrollToBottom();
        }
    }

    private async Task ScrollToBottom()
    {
        try
        {
            await JS.InvokeVoidAsync("eval", "document.querySelector('[data-msg-list]')?.scrollTo(0, document.querySelector('[data-msg-list]')?.scrollHeight)");
        }
        catch
        {
            // Ignore JS interop failures during prerendering
        }
    }

    private async Task HandleScroll()
    {
        // Trigger loading older messages when scrolled near top
        try
        {
            var scrollTop = await JS.InvokeAsync<double>("eval", "document.querySelector('[data-msg-list]')?.scrollTop ?? 1");
            if (scrollTop < 50 && !IsLoadingMore)
            {
                await OnLoadOlderMessages.InvokeAsync();
            }
        }
        catch
        {
            // Ignore JS interop failures
        }
    }
}
