.message-item {
    padding: 8px 16px;
    position: relative;
    border-radius: 4px;
    transition: background-color 0.1s;
}

.message-item:hover {
    background-color: rgba(0, 0, 0, 0.1);
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.message-author {
    font-weight: 700;
    font-size: 0.95rem;
    color: #fff;
}

.message-time {
    font-size: 0.75rem;
    color: #72767d;
}

.message-content {
    color: #dcddde;
    font-size: 0.9rem;
    line-height: 1.4;
    word-wrap: break-word;
}

.reaction-bar {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    margin-top: 6px;
}

.reaction-badge {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    padding: 2px 8px;
    background-color: rgba(114, 137, 218, 0.15);
    border: 1px solid rgba(114, 137, 218, 0.3);
    border-radius: 12px;
    cursor: pointer;
    font-size: 0.82rem;
    color: #dcddde;
    transition: background-color 0.15s;
}

.reaction-badge:hover {
    background-color: rgba(114, 137, 218, 0.3);
}

.reaction-count {
    font-size: 0.75rem;
    font-weight: 600;
}

.thread-link {
    display: inline-block;
    margin-top: 4px;
    padding: 2px 8px;
    font-size: 0.8rem;
    color: #7289da;
    background: none;
    border: none;
    cursor: pointer;
    font-weight: 600;
}

.thread-link:hover {
    text-decoration: underline;
}

.message-actions {
    position: absolute;
    top: -12px;
    right: 16px;
    display: flex;
    gap: 4px;
    background-color: #2f3136;
    border: 1px solid #40444b;
    border-radius: 6px;
    padding: 2px 4px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
    z-index: 10;
}

.action-btn {
    padding: 4px 8px;
    font-size: 0.78rem;
    background: none;
    border: none;
    color: #b9bbbe;
    cursor: pointer;
    border-radius: 4px;
    white-space: nowrap;
}

.action-btn:hover {
    background-color: rgba(255, 255, 255, 0.08);
    color: #fff;
}

.emoji-picker {
    position: absolute;
    top: -12px;
    right: 180px;
    display: flex;
    gap: 2px;
    background-color: #2f3136;
    border: 1px solid #40444b;
    border-radius: 6px;
    padding: 4px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
    z-index: 11;
}

.emoji-btn {
    padding: 4px 6px;
    font-size: 1.1rem;
    background: none;
    border: none;
    cursor: pointer;
    border-radius: 4px;
    transition: background-color 0.1s;
}

.emoji-btn:hover {
    background-color: rgba(255, 255, 255, 0.1);
}

