arguments.file_text:
@page "/chat"
@layout ChatLayout
@rendermode InteractiveServer
@using sv_a6db39f9c5d949e8b5cc28961e285fa2.Models
@using sv_a6db39f9c5d949e8b5cc28961e285fa2.Components.Chat
@using sv_a6db39f9c5d949e8b5cc28961e285fa2.Components.Layout
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-container">
    <div class="chat-sidebar">
        <ChannelSidebar Channels="channels"
                        ActiveChannelId="selectedChannelId"
                        OnChannelSelected="SelectChannel" />
    </div>

    <div class="chat-main @(threadRootMessageId.HasValue ? "" : "expanded")">
        <MessageArea Channel="SelectedChannel"
                     Messages="messages"
                     ThreadSummaries="threadSummaries"
                     IsLoadingMore="isLoadingMore"
                     OnLoadOlderMessages="LoadOlderMessages"
                     OnSendMessage="SendMessage"
                     OnOpenThread="OpenThread"
                     OnReact="HandleReaction" />
    </div>

    @if (threadRootMessageId.HasValue)
    {
        <div class="chat-thread">
            <ThreadPanel RootMessage="threadRootMessage"
                         ThreadMessages="threadMessages"
                         OnClose="CloseThread"
                         OnSendReply="SendThreadReply" />
        </div>
    }
</div>

@code {
    private List<Channel> channels = [];
    private List<Message> messages = [];
    private List<ThreadSummary> threadSummaries = [];
    private List<Message> threadMessages = [];
    private Message? threadRootMessage;

    private int selectedChannelId;
    private int? threadRootMessageId;
    private bool isLoadingMore;
    private int messageSkip;
    private const int PageSize = 30;

    private Channel? SelectedChannel => channels.FirstOrDefault(c => c.Id == selectedChannelId);

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        if (selectedChannelId == channelId && messages.Count > 0) return;

        selectedChannelId = channelId;
        messageSkip = 0;
        messages.Clear();
        threadSummaries.Clear();
        CloseThreadSync();

        var loaded = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        messages = loaded;
        messageSkip = loaded.Count;

        BuildThreadSummaries();
        await ChatService.MarkChannelReadAsync(channelId);

        // Update the channel's unread count locally
        var idx = channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            channels[idx] = channels[idx] with { UnreadCount = 0 };
        }
    }

    private async Task LoadOlderMessages()
    {
        if (isLoadingMore) return;
        isLoadingMore = true;

        var older = await ChatService.GetMessagesAsync(selectedChannelId, messageSkip, PageSize);
        if (older.Count > 0)
        {
            messages.InsertRange(0, older);
            messageSkip += older.Count;
            BuildThreadSummaries();
        }

        isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        var message = await ChatService.SendMessageAsync(selectedChannelId, content, null);
        messages.Add(message);
    }

    private async Task OpenThread(int rootMessageId)
    {
        threadRootMessageId = rootMessageId;
        threadRootMessage = messages.FirstOrDefault(m => m.Id == rootMessageId);
        threadMessages = await ChatService.GetThreadAsync(rootMessageId);
    }

    private void CloseThreadSync()
    {
        threadRootMessageId = null;
        threadRootMessage = null;
        threadMessages.Clear();
    }

    private Task CloseThread()
    {
        CloseThreadSync();
        return Task.CompletedTask;
    }

    private async Task SendThreadReply(string content)
    {
        if (!threadRootMessageId.HasValue) return;

        var reply = await ChatService.SendMessageAsync(selectedChannelId, content, threadRootMessageId.Value);
        threadMessages.Add(reply);

        // Update thread summary in main view
        var existing = threadSummaries.FindIndex(t => t.RootMessageId == threadRootMessageId.Value);
        var summary = new ThreadSummary(threadRootMessageId.Value, threadMessages.Count, reply.SentAt);
        if (existing >= 0)
            threadSummaries[existing] = summary;
        else
            threadSummaries.Add(summary);
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        // Optimistically update the local message
        var msgIndex = messages.FindIndex(m => m.Id == args.MessageId);
        if (msgIndex >= 0)
        {
            var msg = messages[msgIndex];
            var reactions = msg.Reactions.ToList();
            var existingReaction = reactions.FindIndex(r => r.Emoji == args.Emoji);
            if (existingReaction >= 0)
            {
                var r = reactions[existingReaction];
                reactions[existingReaction] = r with { Users = [..r.Users, "You"] };
            }
            else
            {
                reactions.Add(new Reaction(args.Emoji, ["You"]));
            }
            messages[msgIndex] = msg with { Reactions = reactions };
        }
    }

    private void BuildThreadSummaries()
    {
        // Build thread summaries from messages that have replies
        var replyGroups = messages
            .Where(m => m.ReplyToId.HasValue)
            .GroupBy(m => m.ReplyToId!.Value);

        threadSummaries = replyGroups.Select(g => new ThreadSummary(
            g.Key,
            g.Count(),
            g.Max(m => m.SentAt)
        )).ToList();
    }
}

.chat-container {
    display: flex;
    height: 100vh;
    width: 100vw;
    overflow: hidden;
    background-color: #36393f;
    color: #dcddde;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}

.chat-sidebar {
    width: 20%;
    min-width: 200px;
    max-width: 280px;
    flex-shrink: 0;
}

.chat-main {
    flex: 1;
    min-width: 0;
    transition: flex 0.2s ease;
}

.chat-main.expanded {
    flex: 1;
}

.chat-thread {
    width: 25%;
    min-width: 280px;
    max-width: 400px;
    flex-shrink: 0;
}

